# pending/requested mask beside it.
PLAYER_COMPLETED_UPGRADE_MASK = 0x14C
PLAYER_COMPLETED_UPGRADE_MASK_WORDS = 36
UPGRADE_TEMPLATE_INDEX = 0x38

