#: `writeMiniDump(EXCEPTION_POINTERS *ep, BOOL fullDump)` - `cdecl`, two stack arguments, called
#: from the unhandled-exception filter at `0x0043D610`. It resolves `MiniDumpWriteDump` out of the
#: `dbghelp.dll` handle at `0x00DC62EC`, builds the file name, opens it, takes `SeDebugPrivilege`
#: and calls through. `docs/crash-dump-quality.md` derives the whole body.
WRITE_MINI_DUMP = 0x0043BE80
WRITE_MINI_DUMP_BYTES = bytes.fromhex("558bec81ec50010000a1ec62dc00")

#: `xor edi, edi` inside it, at the point the file name has been formatted. Every `push edi` from
#: here to the `MiniDumpWriteDump` call is therefore a literal `NULL`, which is what makes the two
#: at `MINI_DUMP_ARGS` the null user-stream and callback parameters rather than live values.
MINI_DUMP_NULL_EDI = 0x0043BF24
MINI_DUMP_NULL_EDI_BYTES = bytes.fromhex("33ff57576a02")

#: `writeMiniDump`'s frame slots. `..._FULL_DUMP_EBP` is the second argument, the `fulldump` debug
#: flag the engine reads off `Debug+0x9F56`; `..._EXCEPTION_INFO_EBP` is the
#: `MINIDUMP_EXCEPTION_INFORMATION` the function fills at `0x0043BF9D`..`0x0043BFB7`.
MINI_DUMP_FULL_DUMP_EBP = 0x0C
MINI_DUMP_EXCEPTION_INFO_EBP = -0x10

#: The eighteen bytes that push `MiniDumpWriteDump`'s last four arguments: `CallbackParam` and
#: `UserStreamParam` (both `push edi`, both `NULL`), `ExceptionParam`, and the dump type - which
#: the stock code derives as `1` or `2` from the `fulldump` flag and nothing else. `..._RESUME` is
#: the `push esi` that follows with the file handle, the first byte the window does not cover.
MINI_DUMP_ARGS = 0x0043C001
MINI_DUMP_ARGS_BYTES = bytes.fromhex("8a550c33c984d20f95c157578d45f0504151")
MINI_DUMP_ARGS_RESUME = 0x0043C013
MINI_DUMP_ARGS_RESUME_BYTES = bytes.fromhex("56ff154401bd00")

#: The engine's own "Game crash" exception code, raised at `DEBUG_CRASH_RAISE` and recognised by
#: the unhandled-exception filter at `0x0043D673`. Four of the six dumps found in the install root
#: carry it, which is why its (stock, empty) parameter block is worth filling.
DEBUG_CRASH_EXCEPTION_CODE = 0x04560123

#: `Debug::crash(int mode)` - `__thiscall` on the `Debug` singleton (`0x00DC62C0`), the function
#: that formats the crash text, shows the message box and raises. Its three frame slots below are
#: everything the exception record is missing.
#:
#: `..._MESSAGE_EBP` is the formatted crash text: allocated at `0x0043A91E` and filled with the
#: current error record's expression, file and line followed by `..._TAG_EBP`'s literal. It is a
#: heap pointer, so it is readable offline only in a dump that carries the heap.
#: `..._TAG_EBP` is one of two `.rdata` literals chosen at `DEBUG_CRASH_TAG_STORE` by `mode`, and
#: `..._MODE_EBP` is `mode` itself - 1 for an assertion, anything else for an error.
DEBUG_CRASH_MESSAGE_EBP = -0x04
DEBUG_CRASH_TAG_EBP = -0x08
DEBUG_CRASH_MODE_EBP = 0x08

#: `mov dword [ebp-8], 0x00BD4BAC` - the assertion arm of the tag choice, which is what pins
#: `DEBUG_CRASH_TAG_EBP` to a slot holding a pointer rather than a count.
DEBUG_CRASH_TAG_STORE = 0x0043A89B
DEBUG_CRASH_TAG_STORE_BYTES = bytes.fromhex("c745f8ac4bbd00")

#: `mov ecx, [ebp-4]` - the engine's own read of the message pointer, feeding the `MessageBoxA`
#: five instructions later. It sits on the only path that reaches the raise, so asserting it is
#: what says `DEBUG_CRASH_MESSAGE_EBP` is live there.
DEBUG_CRASH_MESSAGE_READ = 0x0043AC2A
DEBUG_CRASH_MESSAGE_READ_BYTES = bytes.fromhex("8b4dfc6810100100")

#: `push edi ; push edi ; push edi ; push 0x04560123` - `RaiseException`'s four arguments, in
#: which `lpArguments` and `nNumberOfArguments` are both zero, so the exception record reaches the
#: dump with an empty `ExceptionInformation[]`. `..._RESUME` is the `call RaiseException` itself,
#: the first byte the window does not cover.
DEBUG_CRASH_RAISE = 0x0043AC57
DEBUG_CRASH_RAISE_BYTES = bytes.fromhex("5757576823015604")
DEBUG_CRASH_RAISE_RESUME = 0x0043AC5F
DEBUG_CRASH_RAISE_RESUME_BYTES = bytes.fromhex("ff15d801bd00")


# quiet-exit: suppress the shutdown-assert minidump.
# The engine's own "Game crash" assert (`DEBUG_CRASH_EXCEPTION_CODE`) fires during a normal
# shutdown; the unhandled-exception filter catches it and writes a minidump, so closing the game
# leaves a `.dmp` every time. `quiet-exit` gates the filter's dump call on `m_quitting`, so the
# artifact is written for a real in-game fault and not for a clean quit.

#: `TheGameEngine` - the singleton pointer variable, not the object. `[GAME_ENGINE]` is the
#: `GameEngine *` (`0x04b750d8` in a shutdown dump). Its `+0x10` byte is `m_quitting`, the flag the
#: main loop reads at `0x00639EC6` (`cmp byte [esi+0x10], bl`) to decide whether to keep running;
#: `docs/render-rate.md` §2 derives both. Set true by `GameEngine::setQuitting` (`0x0093D255`,
#: `mov byte [ecx+0x10], 1 ; ret`) when the app is asked to exit, and stays true through teardown.
GAME_ENGINE = 0x00DE4324

#: `m_quitting`'s offset on the `GameEngine`: a byte, nonzero once the process is on its way out.
GAME_ENGINE_QUITTING = 0x10

#: The `call writeMiniDump` **inside the unhandled-exception filter** `0x0043D610` (the
#: `SetUnhandledExceptionFilter` target, installed at `0x00437EB3` via the `push 0x43D610` at
#: `0x00437EA6`). `esi` holds the `EXCEPTION_POINTERS` and `dl` the `fulldump` flag, both already
#: pushed; the call returns to a `add esp, 8` at `0x0043D753` that cleans them. This is the site
#: every observed `0x04560123` shutdown dump was written from, and the one `quiet-exit` redirects
#: through its `m_quitting` gate. The image's other `call writeMiniDump` (`0x0043818B`, in a
#: wrapper with no static callers) is left alone.
WRITE_MINI_DUMP_CALL_FILTER = 0x0043D74E
WRITE_MINI_DUMP_CALL_FILTER_BYTES = bytes.fromhex("e82de7ffff")


# --- combo-horde recruitment -------------------------------------------------------------------
# Derived in `docs/combo-horde-recruitment.md`. A horde produced by a building never fills itself:
# `HordeContain::onObjectCreated` returns at its second instruction when the object has a
# producer, and the building fills it instead - through a production queue entry that carries one
# `ThingTemplate` and one count, fed by a getter that answers only for single-payload hordes.

#: `HordeContain::onObjectCreated` - module vtable slot `+0x70`, shared by `HordeContain`,
#: `HorseHordeContain` and `AODHordeContain` (slots `0x00C5B668`, `0x00C5C2F8`, `0x00C5D460`).
HORDE_CONTAIN_ON_OBJECT_CREATED = 0x00871B9B
HORDE_CONTAIN_ON_OBJECT_CREATED_ENTRY = bytes.fromhex("b8dff7b900e84bb31c00")

#: `mov eax, [esi+8]` / `mov eax, [eax+0x78]` - the producer read whose result the very next
#: instruction turns into "skip the whole function". The six bytes `combo-horde-recruitment`
#: replaces with a `call` into its cave.
HORDE_CONTAIN_PRODUCED_GATE = 0x00871BAB
HORDE_CONTAIN_PRODUCED_GATE_BYTES = bytes.fromhex("8b46088b4078")

#: `test eax, eax` / `jne <epilogue>` - the branch itself, left stock by the patch, which only
#: changes what `eax` holds when it is reached. Asserted so a build that moved the jump cannot be
#: patched into falling through unconditionally.
HORDE_CONTAIN_PRODUCED_GATE_TEST = 0x00871BB1
HORDE_CONTAIN_PRODUCED_GATE_TEST_BYTES = bytes.fromhex("85c00f857b010000")

#: The `call TransportContain::createPayload` the gate skips - the one path that reads every
#: `InitialPayload` entry.
HORDE_CONTAIN_CREATE_PAYLOAD_CALL = 0x00871BBB
HORDE_CONTAIN_CREATE_PAYLOAD_CALL_BYTES = bytes.fromhex("e83a86ffff")

#: `TransportContain::createPayload` - outer loop over the payload list, inner loop over each
#: entry's count. `__thiscall`, no arguments.
TRANSPORT_CONTAIN_CREATE_PAYLOAD = 0x0086A1FA
TRANSPORT_CONTAIN_CREATE_PAYLOAD_ENTRY = bytes.fromhex("558bec83ec1456578bf98b47048945ec")

#: `mov dword [esi+0x2a8], 0x64` in the `HordeContain` constructor - the strength percent the
#: trim block below the gate reads. 100 means "destroy nobody", which is what makes it safe for a
#: recruited combo horde to run that block for the first time.
HORDE_CONTAIN_FULL_STRENGTH_INIT = 0x00872972
HORDE_CONTAIN_FULL_STRENGTH_INIT_BYTES = bytes.fromhex("c786a802000064000000")

#: The contain-module interface's `+0x24`: the `InitialPayload` template name, returned **only**
#: when the list holds exactly one entry and the empty string otherwise. The single point at
#: which a combo horde's mix is discarded.
HORDE_CONTAIN_PAYLOAD_NAME = 0x0087048F
HORDE_CONTAIN_PAYLOAD_NAME_ENTRY = bytes.fromhex("558bec518b91e8feffff8b8aa4000000")
#: `cmp esi, 1` / `jne <empty string>` inside it - the defect, in two instructions.
HORDE_CONTAIN_PAYLOAD_NAME_SINGLETON_TEST = 0x008704B2
HORDE_CONTAIN_PAYLOAD_NAME_SINGLETON_TEST_BYTES = bytes.fromhex("83fe01750d")

#: `call [eax+0x24]` in `ProductionUpdate::update` - the only caller of
#: `HORDE_CONTAIN_PAYLOAD_NAME` in the image, and therefore the whole of recruitment's knowledge
#: of what a horde is made of.
PRODUCTION_HORDE_PAYLOAD_CALL = 0x008A2C91
PRODUCTION_HORDE_PAYLOAD_CALL_BYTES = bytes.fromhex("ff5024")

#: The queue-entry rewrite that follows it: `entry->template = the payload`,
#: `entry->total = Slots + 1`, `entry+0x34 = 1`. Skipped entirely when the getter answered "".
PRODUCTION_HORDE_ENTRY_REWRITE = 0x008A2CC4
PRODUCTION_HORDE_ENTRY_REWRITE_BYTES = bytes.fromhex("8b4dbc4083632800894b08894320c6433401")

#: `mov ecx, [ebx+8]` - the batch loop's read of the one template every object in this entry is
